const c = $('Controle acces').first().json;
if (c.vocal || (c.nb_jour !== 101 && c.nb_jour !== 151)) return [];
const admins = $('Lire utilisateurs').all().map(i => i.json).filter(u => u.actif && u.role === 'admin' && u.telegram_id);
const text = c.nb_jour === 101
  ? 'Info bot : ' + c.nom + ' a depasse 100 questions aujourd hui (limite 150).'
  : 'Alerte bot : ' + c.nom + ' a atteint la limite de 150 questions aujourd hui, il est bloque jusqu a demain.';
return admins.map(a => ({ json: { chat_id: String(a.telegram_id), text } }));

if (!$('Preparer reponse').isExecuted) return [];
const p = $('Preparer reponse').first().json;
const brut = String(p.copie || '').trim();
if (!brut) return [];
// Garde-fou : jamais de reference ni de prix dans le message distributeur (c est au distributeur de verifier)
const copie = brut.split('\n').map(l => l
  .replace(/\b(r[ée]f[ée]rence|r[ée]f)\.?\s*(de\s+(la\s+)?pi[eè]ce\s*)?[:=-]?\s*[A-Z0-9][A-Z0-9./-]*\d[A-Z0-9./-]*/gi, '')
  .replace(/\(?\s*\d[\d\s.,]*\s*(€|eur\b|euros?\b)\s*(HT|TTC)?\s*\)?/gi, '')
  .replace(/\s*,\s*,/g, ',').replace(/\s{2,}/g, ' ').trimEnd()
).filter(l => !/^\s*(prix|tarif)[^:]*:\s*$/i.test(l)).join('\n').trim();
const fournisseurs = $input.all().map(i => i.json).filter(f => f && f.marque && f.email && f.actif !== false);
const texte = (p.text || '') + '\n' + copie;
const escRe = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
let f = null;
for (const x of fournisseurs) {
  const re = new RegExp('\\b' + escRe(x.marque) + '\\b', 'i');
  if (re.test(copie) || re.test(texte)) { f = x; break; }
}
let mail_url = '', bouton_texte = '';
if (f) {
  let modele = '';
  const m1 = copie.match(new RegExp(escRe(f.marque) + '\\s*[:,-]?\\s*(?:mod[eè]le\\s*:?\\s*)?([A-Z0-9][A-Z0-9./-]*\\d[A-Z0-9./-]*)', 'i'));
  if (m1) modele = m1[1];
  if (!modele) { const m2 = copie.match(/mod[eè]le\s*:?\s*([A-Z0-9][A-Z0-9./-]*\d[A-Z0-9./-]*)/i); if (m2) modele = m2[1]; }
  if (!modele) { const m3 = copie.match(/\b([A-Z]{2,6}[A-Z0-9]*-[A-Z0-9./-]*\d[A-Z0-9./-]*)\b/); if (m3) modele = m3[1]; }
  modele = modele.replace(/[.,;:-]+$/, '');
  const sujet = 'ClimatPro - Demande de prix piece ' + f.marque + (modele ? ' ' + modele.toUpperCase() : '');
  const q = 'to=' + encodeURIComponent(String(f.email).trim()) + '&cc=' + encodeURIComponent('contact@climatpro.fr') + '&s=' + encodeURIComponent(sujet) + '&b=' + encodeURIComponent(copie);
  mail_url = 'https://n8n.climatpro.fr/webhook/mailto?' + q;
  bouton_texte = 'Envoyer par email a ' + String(f.email).trim();
}
return [{ json: { chat_id: p.chat_id, text: copie, mail_url, bouton_texte } }];

const upd = $('Message Telegram').first().json;
const msg = upd.message || {};
if (!msg.chat || msg.chat.type !== 'private') return [];
const chatId = String(msg.chat.id);
const users = $input.all().map(i => i.json);
const u = users.find(x => x.actif && String(x.telegram_id) === chatId);
if (!u) return [];
const role = String(u.role || '');
const base = { chat_id: chatId, interfast_id: Number(u.interfast_id), role, nom: String(u.nom || ''), photo_id: '' };
if (!msg.text && (msg.voice || msg.audio || msg.video_note)) {
  return [{ json: { ...base, question: '[message vocal]', vocal: true, quota_ok: false, nb_jour: 0 } }];
}
let photo_id = '';
if (Array.isArray(msg.photo) && msg.photo.length) photo_id = String(msg.photo[msg.photo.length - 1].file_id || '');
else if (msg.document && /^image\//.test(String(msg.document.mime_type || ''))) photo_id = String(msg.document.file_id || '');
let q = String(msg.text || msg.caption || '').trim();
if (photo_id) q = (q ? q + '\n' : '') + '[Photo jointe : lis-la (plaque signaletique, etiquette, code erreur). Si le texte ou la photo contient un code defaut (ex A6, E04, 0011, defaut U4), c est une demande de fiche code defaut : traite-la tout de suite avec les outils, sans demander de confirmation. Si le texte contient une autre demande, traite-la directement. Seulement si il n y a ni code ni demande, donne la marque et le modele lus, puis demande quelle piece ou quelle info est voulue.]';
if (!q) return [];
const QUOTA = 150;
const jour = DateTime.now().setZone('Europe/Paris').toISODate();
const st = $getWorkflowStaticData('global');
if (!st.quota || st.quota.jour !== jour) st.quota = { jour, n: {} };
st.quota.n[chatId] = (st.quota.n[chatId] || 0) + 1;
const quota_ok = role === 'admin' || st.quota.n[chatId] <= QUOTA;
return [{ json: { ...base, photo_id, question: q.slice(0, 1200), vocal: false, quota_ok, nb_jour: st.quota.n[chatId] } }];

const p = $input.first().json;
const ctx = $('Controle acces').first().json;
if (ctx.role === 'admin') return [];
const q = String(p.question || ''), r = String(p.text || '');
const sens = /(prix|tarif|co[uû]t|marge|chiffre d.?affaires|\bca\b|salaire|paie|b[ée]n[ée]fice|facture|montant|€|euro|mot de passe|password|identifiant|banque|\brib\b|iban)/i;
const piece = /(pi[eè]ce|r[ée]f[ée]rence|\br[ée]f\b|hitachi|dispo|stock|carte|moteur|sonde|compresseur|ventilateur)/i;
const sensMarge = /(marge|chiffre d.?affaires|\bca\b|salaire|paie|b[ée]n[ée]fice|facture|mot de passe|password|identifiant|banque|\brib\b|iban|prix d.?achat)/i;
const refus = /(pas acc[eè]s|n.?ai pas acc[eè]s|je ne peux pas|pas autoris|non autoris|confidenti)/i;
const motifs = [];
if (piece.test(q) ? sensMarge.test(q) : sens.test(q)) motifs.push('sujet sensible');
if (refus.test(r)) motifs.push('refus du bot');
if (!motifs.length) return [];
const admins = $('Lire utilisateurs').all().map(i => i.json).filter(u => u.actif && u.role === 'admin' && u.telegram_id);
return admins.map(a => ({ json: { chat_id: String(a.telegram_id), text: 'Alerte bot (' + motifs.join(', ') + ')\n' + ctx.nom + ' a demandé : « ' + q.slice(0, 300) + ' »\nRéponse : ' + r.slice(0, 400) } }));

const c = $('Controle acces').first().json;
const it = $input.first();
const b = it.binary || {};
for (const k of Object.keys(b)) { if (!b[k].mimeType || !/^image\//.test(b[k].mimeType)) b[k].mimeType = 'image/jpeg'; }
return [{ json: c, binary: b }];

const c = $input.first().json;
const text = c.vocal
  ? 'Je ne lis pas encore les messages vocaux. Dicte ta question avec le micro du clavier (elle s ecrit en texte), ou tape-la.'
  : 'Tu as atteint la limite de 150 questions pour aujourd hui. Pour la suite, appelle Laurent. Le compteur repart demain.';
return [{ json: { chat_id: c.chat_id, nom: c.nom, question: c.question, text } }];

const ctx = $('Controle acces').first().json;
let t = String(($input.first().json || {}).output || '').trim();
if (!t) t = 'Desole, je n ai pas pu repondre. Reessaie dans un instant.';
t = t.replace(/\*\*/g, '').replace(/[–—]/g, '-');
const parts = t.split(/\s*={3}\s*COPIER\s*={3}\s*/i);
const main = parts[0].trim();
const copie = parts.length > 1 ? parts.slice(1).join('\n').trim() : '';
let t1 = main || 'Message pour le distributeur :';
if (copie && main) t1 += '\n\nMessage pour le distributeur dans la bulle suivante : bouton Envoyer par email, ou appui long pour copier.';
if (t1.length > 4000) t1 = t1.slice(0, 3990) + '...';
return [{ json: { chat_id: ctx.chat_id, nom: ctx.nom, question: ctx.question, text: t1, full: t, copie: copie.slice(0, 3990) } }];
